function baseHeaders(req?:IncomingMessage,contentType="application/json; charset=utf-8"){const origin=req?.headers.origin;return {"content-type":contentType,"access-control-allow-origin":origin===allowedOrigin?origin:allowedOrigin,"access-control-allow-credentials":"true","access-control-allow-headers":"authorization,content-type,x-dev-user,x-request-id,x-file-name","access-control-allow-methods":"GET,POST,PATCH,DELETE,OPTIONS","vary":"Origin","x-content-type-options":"nosniff","cache-control":"no-store"}}
