const cookieValue=(req:IncomingMessage,name:string)=>{const item=String(req.headers.cookie??"").split(";").map(value=>value.trim()).find(value=>value.startsWith(`${name}=`));return item?decodeURIComponent(item.slice(name.length+1)):null};
const sessionCookie=(token:string,maxAge=LOCAL_SESSION_SECONDS)=>`${LOCAL_SESSION_COOKIE}=${encodeURIComponent(token)}; Path=/; HttpOnly; SameSite=Lax; Max-Age=${maxAge}${process.env.NODE_ENV==="production"?"; Secure":""}`;
async function derivePassword(password:string,salt:Buffer){return new Promise<Buffer>((resolve,reject)=>scrypt(password,salt,64,(error,key)=>error?reject(error):resolve(key))) }
async function passwordHash(password:string){const salt=randomBytes(16),key=await derivePassword(password,salt);return `scrypt$${salt.toString("base64url")}$${key.toString("base64url")}`}
