function normalizedAccountEmail(value:unknown){const email=String(value??"").trim().toLowerCase();if(!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email))throw new Error("ACCOUNT_EMAIL_INVALID");return email}
