async function issueLocalSession(userId:string){const token=randomBytes(32).toString("base64url"),expiresAt=new Date(Date.now()+LOCAL_SESSION_SECONDS*1000);await (prisma as any).localSession.create({data:{userId,tokenHash:tokenHash(token),expiresAt}});return {token,expiresAt}}
async function localSessionActor(req:IncomingMessage):Promise<{userId:string;email:string}|null>{if(!localPasswordAuthEnabled())return null;const token=cookieValue(req,LOCAL_SESSION_COOKIE);if(!token)return null;const session=await (prisma as any).localSession.findFirst({where:{tokenHash:tokenHash(token),revokedAt:null,expiresAt:{gt:new Date()}}});if(!session)return null;const user=await prisma.userIdentity.findUnique({where:{id:session.userId},select:{id:true,email:true,status:true}});return user?.status==="active"?{userId:user.id,email:user.email}:null}
async function actor(req:IncomingMessage):Promise<ServiceActor>{const local=await localSessionActor(req);if(local)return {...local,requestId:String(req.headers["x-request-id"]??randomUUID()),correlationId:randomUUID()};const identity=await provider.authenticate({authorization:req.headers.authorization,devUser:String(req.headers["x-dev-user"]??"")});if(!identity)throw new Error("AUTH_REQUIRED");const user=await repo.ensureUser({provider:provider instanceof DevelopmentIdentityProvider?"development":"oidc",subject:identity.subject,email:identity.email,displayName:identity.displayName});return {userId:user.id,email:user.email,requestId:String(req.headers["x-request-id"]??randomUUID()),correlationId:randomUUID()}}
