const domainRateWindows=new Map<string,number[]>();
function assertDomainRateLimit(key:string,limit:number,windowMs:number){const now=Date.now(),recent=(domainRateWindows.get(key)??[]).filter(at=>at>now-windowMs);if(recent.length>=limit)throw new Error("DOMAIN_RATE_LIMITED");recent.push(now);domainRateWindows.set(key,recent)}
function status(code:string){if(code.startsWith("AUTH_"))return 401;if(code.startsWith("FORBIDDEN")||code==="WORKSPACE_ACCESS_DENIED")return 403;if(code==="NOT_FOUND"||code.endsWith("_NOT_FOUND"))return 404;if(code.includes("CONFLICT")||code==="CONCURRENCY_CONFLICT"||["DOMAIN_ALREADY_CLAIMED","DOMAIN_HAS_ACTIVE_SENDS"].includes(code))return 409;if(code==="DOMAIN_RATE_LIMITED")return 429;if(code==="REQUEST_TOO_LARGE")return 413;if(["AWS_ACCESS_DENIED","PROVIDER_AUTHENTICATION_FAILED"].includes(code))return 502;if(["AWS_THROTTLED","SES_PROVIDER_UNAVAILABLE","DNS_TIMEOUT","DNS_SERVFAIL"].includes(code))return 503;return 400}
function publicErrorMessage(code:string,message:string){
  const safe:Record<string,string>={
    DOMAIN_ALREADY_CLAIMED:"This domain is already connected to another workspace.",
    DOMAIN_CROSS_WORKSPACE_CONFLICT:"This domain is already connected to another workspace.",
    DNS_DELEGATION_PENDING:"Add the four NS records and the ownership TXT record shown, then wait for automatic verification.",
    OWNERSHIP_VERIFICATION_PENDING:"Add the ownership TXT record shown. Velivoo checks it automatically.",
    DKIM_RECORDS_PENDING:"Email authentication records are not visible in public DNS yet.",
    SES_VERIFICATION_PENDING:"DNS is visible, but email verification is still processing.",
    SES_VERIFICATION_FAILED:"We could not verify this sending domain. Review the DNS records.",
    MAIL_FROM_PENDING:"Velivoo is finishing branded email routing.",
    AWS_ACCESS_DENIED:"Velivoo infrastructure requires administrator attention.",
    AWS_THROTTLED:"Verification is temporarily delayed. Try again shortly.",
    DNS_TIMEOUT:"DNS verification timed out. Velivoo will retry automatically.",
    DNS_SERVFAIL:"The public DNS resolver returned SERVFAIL. Velivoo will retry automatically.",
    ROUTE53_CREATE_FAILED:"Velivoo could not prepare the sending domain. Try again or contact support.",
    VANITY_NS_NOT_APPLIED:"Domain infrastructure is still being prepared.",
    DOMAIN_RATE_LIMITED:"Too many domain checks were requested. Try again shortly.",
    DOMAIN_PROVISIONING_IN_PROGRESS:"This domain is already being checked. Try again shortly.",
    DOMAIN_REMOVAL_CONFIRMATION_REQUIRED:"Type the exact domain name to confirm its removal.",
    DOMAIN_HAS_SENDER_IDENTITIES:"Remove or move every sender identity that uses this domain before removing it.",
    DOMAIN_HAS_ACTIVE_SENDS:"Wait for the current send to finish or reconcile its delivery status, then try disconnecting again.",
    DNS_ZONE_CONTAINS_UNMANAGED_RECORDS:"Velivoo could not remove the hosted zone because it contains records that were not created by this platform.",
  };
  if(safe[code])return safe[code]!;
  if(code==="DOMAIN_PROVIDER_NOT_CONFIGURED"||code==="SES_REGION_NOT_CONFIGURED")return "Branded sending-domain setup is not configured on this server.";
  if(["EMAIL_USED_INSTEAD_OF_DOMAIN","URL_USED_INSTEAD_OF_DOMAIN","INVALID_DOMAIN","DOMAIN_MUST_BE_REGISTRABLE_ROOT"].includes(code))return "Enter a registrable root domain like hollapic.com, not an email address, URL, or subdomain.";
  return message;
}

async function infrastructureReadiness(workspaceId:string){
  const [providerConfig,gates]=await Promise.all([
    prisma.workspaceProviderConfig.findFirst({where:{workspaceId,provider:"ses",providerStatus:"active"},select:{configurationSetName:true}}),
    prisma.phase0GateEvidence.findMany({where:{checkKey:{in:["real.sns.signature","real.sns.subscription","real.unsubscribe.endpoint","real.feedback.endpoint"]}},select:{checkKey:true,status:true}}),
  ]);
  const passed=new Set(gates.filter(gate=>gate.status==="passed").map(gate=>gate.checkKey));
  return {
    feedbackReady:Boolean(process.env.EMAIL_PLATFORM_SNS_TOPIC_ARN?.trim()&&providerConfig?.configurationSetName&&passed.has("real.sns.signature")&&passed.has("real.sns.subscription")&&passed.has("real.feedback.endpoint")),
    unsubscribeReady:passed.has("real.unsubscribe.endpoint"),
  };
}

async function refreshPublicUnsubscribeEvidence(){
  const configured=process.env.EMAIL_PLATFORM_PUBLIC_BASE_URL?.trim();
  let endpoint:URL|null=null;
  try{if(configured)endpoint=new URL("/health/unsubscribe",configured)}catch{/* Persist a blocked diagnostic below. */}
  const publicHttps=endpoint?.protocol==="https:"&&!["localhost","127.0.0.1","::1"].includes(endpoint.hostname.toLowerCase());
  let passed=false,diagnostic=publicHttps?"PUBLIC_UNSUBSCRIBE_PROBE_FAILED":"PUBLIC_HTTPS_URL_REQUIRED";
  if(publicHttps&&endpoint){
    try{const response=await fetch(endpoint,{signal:AbortSignal.timeout(5000),headers:{accept:"text/plain"}});passed=response.ok;diagnostic=response.ok?"PUBLIC_UNSUBSCRIBE_REACHABLE":`PUBLIC_UNSUBSCRIBE_HTTP_${response.status}`}catch(error){diagnostic=error instanceof Error?error.name:"PUBLIC_UNSUBSCRIBE_PROBE_FAILED"}
  }
  await prisma.phase0GateEvidence.upsert({
    where:{checkKey:"real.unsubscribe.endpoint"},
    create:{checkKey:"real.unsubscribe.endpoint",status:passed?"passed":"blocked",evidenceJson:{hostname:endpoint?.hostname??null,protocol:endpoint?.protocol??null,diagnostic}},
    update:{status:passed?"passed":"blocked",evidenceJson:{hostname:endpoint?.hostname??null,protocol:endpoint?.protocol??null,diagnostic},checkedAt:new Date()},
  });
}

